// The ROKCT card's sketch sheet (hosting_sdk 1.10.0). Ray: "4 logos all
// drawn by hand on a plane divided by 4 like a cross. Then on the side a
// selected logo no longer hand drawn", then "let the drawings be rough
// like a scratchpad". A gridded scratchpad page split by a quick pen cross,
// a fast pen doodle in each quarter:
//
//   A  wordmark   ROKCT in tight condensed capitals; the O an orbit, its dot
//                 the R's registration dot. A softer lowercase try, struck out.
//   B  nose cone  a rocket's tip and nothing else, the porthole as the dot.
//                 A literal little rocket, crossed out.
//   C  the R      the ROKCT mark, its outline traced from rokct-r.svg's own
//                 path; circled and ticked: the one picked.
//   D  seal       a round stamp: the name around the ring, a serif R inside.
//                 A square badge, struck out.
//
// Everything is vector. Every line is a hand-authored stroke drawn two or
// three times, each pass jittered, bowed and overshooting its corners (the
// paths are generated once with a fixed seed and committed as data), with
// scribbled hatching clipped to the shape, and a light noise filter for
// the pen's edge. Notes are in Caveat (fonts/OFL-caveat.txt). The ink is
// currentColor and the paper a token, so the sheet follows the panel's
// light or dark theme. Server component; no state.

/** The ROKCT mark's own outline, verbatim from public/studio/logo/rokct-r.svg (RokctAI_frontend public/images/logo.svg); sketch C is traced from it. */
export const ROKCT_R_PATH =
  "M818 10c17,0 34,1 50,1l779 317c45,57 80,120 105,188l-62 706c-2,4 -4,7 -7,11 -73,111 -175,198 -306,260l257 375 -27 306 -418 0 -393 -575 -244 0 139 -1589 127 0zm-532 2164l-277 0 0 -2164 467 0 -190 2164z";

function Hand({ x, y, children, size = 28, rot = -2, anchor, className = "" }: { x: number; y: number; children: string; size?: number; rot?: number; anchor?: "end" | "middle"; className?: string }) {
  return (
    <text x={x} y={y} className={`sk-hand ${className}`} fontSize={size} textAnchor={anchor} transform={`rotate(${rot} ${x} ${y})`}>
      {children}
    </text>
  );
}

function Label({ k, name, on }: { k: string; name: string; on?: boolean }) {
  return (
    <g className={on ? "sk-lab on" : "sk-lab"} transform="rotate(-3 40 70)">
      <text x={40} y={74} className="sk-hand sk-k">
        {k}
      </text>
      <text x={78} y={72} className="sk-hand sk-name">
        {name}
      </text>
    </g>
  );
}

